--
-- Table structure for table `inventarios`
--

DROP TABLE IF EXISTS `inventarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventarios` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `donativo_id` bigint unsigned NOT NULL,
  `categoria_producto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_producto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Nuevo',
  `fecha_caducidad` date DEFAULT NULL,
  `clave_sat` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modalidad` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clave_unidad` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cantidad` int NOT NULL,
  `cantidad_actual` decimal(10,2) NOT NULL DEFAULT '0.00',
  `precio_venta_unitario` decimal(10,2) NOT NULL DEFAULT '0.00',
  `precio_venta_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `precio_unitario_deducible` decimal(10,2) NOT NULL DEFAULT '0.00',
  `monto_deducible_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `catalogo_producto_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
